int register_genl_family(struct genl_family *family) {
    int err = 0;

    if (!family) {
        return -EINVAL;
    }

    if (family->n_attrs > GENL_MAX_ATTR) {
        return -EINVAL;
    }

    if (family->n_ops > GENL_MAX_OPS) {
        return -EINVAL;
    }

    if (family->id != GENL_ID_GENERATE && family->id >= GENL_ID_MIN && family->id < GENL_ID_MAX) {
        return -EINVAL;
    }

    if (family->mcgrps && family->n_mcgrps > GENL_MAX_MCGRP) {
        return -EINVAL;
    }

    if (family->ops) {
        for (int i = 0; i < family->n_ops; i++) {
            if (!family->ops[i].cmd || family->ops[i].cmd >= GENL_MAX_OPS) {
                return -EINVAL;
            }
            if (!family->ops[i].doit && !family->ops[i].dumpit) {
                return -EINVAL;
            }
        }
    }

    if (family->name && strlen(family->name) >= GENL_NAMSZ) {
        return -EINVAL;
    }

    if (family->mcgrps) {
        for (int i = 0; i < family->n_mcgrps; i++) {
            if (!family->mcgrps[i].name || strlen(family->mcgrps[i].name) >= GENL_NAMSZ) {
                return -EINVAL;
            }
        }
    }

    if (family->n_attrs) {
        family->attrbuf = kmalloc(family->n_attrs, GFP_KERNEL);
        if (!family->attrbuf) {
            return -ENOMEM;
        }
    }

    if (family->id == GENL_ID_GENERATE) {
        family->id = genl_get_unique_id();
        if (family->id < 0) {
            err = family->id;
            goto out_free_attrbuf;
        }
    }

    if (family->mcgrps) {
        for (int i = 0; i < family->n_mcgrps; i++) {
            if (family->mcgrps[i].id >= GENL_MAX_MCGRP) {
                err = -EINVAL;
                goto out_unregister_id;
            }
        }
    }

    return 0;

out_unregister_id:
    genl_unregister_id(family->id);
out_free_attrbuf:
    kfree(family->attrbuf);
    return err;
}
